    "Whisk soy sauce, mirin, honey, garlic, and ginger together, then dissolve cornstarch in the water and stir into the sauce.",
    "Pat chicken thighs completely dry with kitchen paper.",
    "Heat a pan over medium-high heat with a little oil — sear the chicken smooth side down 5 minutes without moving until deep golden.",
