	"Cook jasmine rice and keep warm.",
	"Whisk all peanut sauce ingredients together until smooth and glossy — the coconut milk gives it body without needing extra water.",
	"Brine chicken breasts in salted water (1 tsp salt per 500ml) for 15 minutes if possible — pat dry.",
