    "Cook chicken in a hot pan over medium-high heat — 5–6 minutes per side, until deeply golden and internal temp 74°C. Rest 5 minutes, then slice thin.",
    "Whisk tahini with lemon juice, garlic, water, and salt until smooth (it will seize first, then become pourable — keep whisking).",
