"korean-egg-fried-rice": {
  image: null,
  video: null,
  ingredients: [
    { section: "Protein", items: [{ name: "Eggs (whole)", amt: "{{proteinG}}g raw" }] },
    { section: "Carb Base", items: [{ name: "Day-old jasmine rice (cooked)", amt: "150g", id: "rice_cooked" }] },
    { section: "Sauce", items: [
      { name: "Gochujang", amt: "1 tbsp" },
      { name: "Soy sauce", amt: "1.5 tbsp" },
      { name: "Sesame oil", amt: "1 tsp" },
      { name: "Garlic (minced)", amt: "2 cloves" },
    ]},
    { section: "To Serve", items: [
      { name: "Spring onion", amt: "3 stalks" },
      { name: "Sesame seeds", amt: "1 tsp" },
      { name: "Kimchi (optional)", amt: "60g" },
      { name: "Neutral oil", amt: "1 tsp" },
    ]},
  ],
  steps: [
    "Mix gochujang, soy sauce, sesame oil, and garlic — set aside.",
    "Heat a wok over maximum heat with oil until just smoking.",
    "Add cold day-old rice — press flat against the hot wok and let it fry undisturbed for 1–2 minutes until the bottom begins to crisp.",
    "Toss the rice, push to the sides, crack the eggs into the centre — scramble quickly until half-set, then fold into the rice.",
    "Pour the sauce over the rice and toss constantly over high heat for 1 minute until everything is evenly coated.",
    "Serve immediately topped with spring onion, sesame seeds, and kimchi on the side if using.",
  ],
  hacks: [
    { title: "Day-Old Rice Only", text: "Fresh rice is too moist and clumps in the wok. Day-old rice from the fridge has dried out enough to fry and get slightly crispy. If cooking today, spread fresh rice on a tray and refrigerate for 1 hour minimum." },
    { title: "Gochujang = 80/20 Move", text: "One tablespoon of gochujang adds sweetness, heat, depth, and colour to basic egg fried rice — transforming a simple fridge-clear dish into something that tastes intentionally Korean." },
  ],
  notes: "Designed to use leftover rice. Any leftover vegetables can go in at step 3 — frozen corn, frozen peas, and leftover veg all work well. Kimchi on the side is the perfect acidic counterpoint.",
},

"shakshuka-middle-eastern-eggs": {
  image: null,
  video: null,
  ingredients: [
    { section: "Protein", items: [{ name: "Eggs (whole)", amt: "{{proteinG}}g raw" }] },
    { section: "Carb Base", items: [{ name: "Sourdough or crusty bread", amt: "{{carbG}}g" }] },
    { section: "Tomato Sauce", items: [
      { name: "Canned crushed tomatoes", amt: "400g" },
      { name: "Red bell pepper (diced)", amt: "1 large" },
      { name: "Onion (diced)", amt: "1 medium" },
      { name: "Garlic (minced)", amt: "4 cloves" },
      { name: "Cumin", amt: "1.5 tsp" },
      { name: "Smoked paprika", amt: "1 tsp" },
      { name: "Chili flakes", amt: "0.5 tsp" },
      { name: "Tomato paste", amt: "1 tbsp" },
      { name: "Olive oil", amt: "1 tbsp" },
      { name: "Salt & pepper", amt: "to taste" },
    ]},
    { section: "Toppings", items: [
      { name: "Feta cheese (crumbled)", amt: "50g" },
      { name: "Fresh parsley or coriander", amt: "small handful" },
    ]},
  ],
  steps: [
    "Heat olive oil in a wide, deep pan over medium heat — fry onion and pepper for 6–7 minutes until softened and beginning to colour.",
    "Add garlic and tomato paste — cook 1–2 minutes until fragrant and the paste darkens slightly.",
    "Add cumin, smoked paprika, and chili flakes — bloom 30 seconds in the oil, stirring.",
    "Pour in crushed tomatoes, season with salt and pepper — simmer 10 minutes until slightly thickened.",
    "Make 4 wells in the sauce with a spoon and crack one egg into each well.",
    "Cover the pan and cook on medium-low heat for 6–8 minutes — whites should be set but yolks still runny.",
    "Crumble feta generously over the top, scatter fresh herbs, and serve straight from the pan with crusty bread.",
  ],
  hacks: [
    { title: "Bloom the Spices", text: "Adding dry spices to the hot pan before the liquid — letting them sizzle for 30 seconds — releases the aromatic oils and makes the sauce taste richer and more developed. It's the most impactful 30 seconds in this recipe." },
    { title: "Feta as a Topping", text: "Crumbling feta over the finished shakshuka adds saltiness, creaminess, and protein. It looks stunning against the red sauce and costs almost nothing in extra calories." },
  ],
  notes: "Serve straight from the pan for maximum visual impact. Check the eggs at 6 minutes — this is the point of runny yolks. 8 minutes gives set yolks. The sauce can be made 2 days ahead and refrigerated.",
},

"japanese-tamago-gohan-bowl": {
  image: null,
  video: null,
  ingredients: [
    { section: "Protein", items: [{ name: "Eggs (whole)", amt: "{{proteinG}}g raw" }] },
    { section: "Carb Base", items: [{ name: "Short grain Japanese rice (dry)", amt: "{{carbG}}g" }] },
    { section: "Sauce", items: [
      { name: "Soy sauce", amt: "1.5 tsp per bowl" },
      { name: "Sesame oil", amt: "0.5 tsp per bowl" },
      { name: "Togarashi or chili flakes", amt: "0.5 tsp per bowl" },
    ]},
    { section: "To Serve", items: [
      { name: "Spring onion", amt: "2 stalks" },
      { name: "Nori sheets (optional)", amt: "2 small sheets" },
      { name: "Sesame seeds", amt: "1 tsp" },
    ]},
  ],
  steps: [
    "Cook short-grain rice until fluffy and sticky — keep very hot, do not let it cool.",
    "Scoop steaming rice into two bowls.",
    "Crack one whole raw egg per bowl directly over the steaming rice.",
    "Immediately drizzle soy sauce and sesame oil over each bowl — the heat of the rice begins to lightly cook the egg.",
    "Use chopsticks or a fork to vigorously stir the egg into the rice for 30–60 seconds until you have a creamy, slightly pale, frothy mixture.",
    "Top with spring onion, togarashi, sesame seeds, and a piece of nori — eat immediately.",
  ],
  hacks: [
    { title: "Rice Must Be Steaming Hot", text: "The entire dish depends on the rice being hot enough to gently cook the egg as you stir. If the rice has cooled, reheat it in a small pot with a splash of water over medium heat until actively steaming before cracking the egg. Room temperature rice gives you raw egg on rice — not the goal." },
    { title: "Vigorous Stirring = Creamy Texture", text: "The more vigorously and longer you stir, the more air you incorporate and the creamier and frothier the texture becomes. This technique is what transforms raw egg on rice into something genuinely silky." },
  ],
  notes: "Use the freshest eggs possible — this dish uses raw egg. Togarashi at Asian supermarkets. Nori sheets available at Asian supermarkets. Great ASMR-style close-up content.",
},

