  "greek-lemon-herb-chicken-bowl": {
    image: null,
    video: "",
    ingredients: [
      { section: "Rice", items: [
        { name: "Jasmine rice (dry)", amt: "{{carbG}}g" },
        { name: "Water or chicken broth", amt: "as needed" },
      ]},
      { section: "Chicken", items: [
        { name: "Chicken breast (boneless, skinless)", amt: "{{proteinG}}g raw" },
        { name: "Olive oil", amt: "1 tsp" },
        { name: "Lemon juice", amt: "2 tbsp" },
        { name: "Lemon zest", amt: "1 tsp" },
        { name: "Garlic powder", amt: "½ tsp" },
        { name: "Dried oregano", amt: "1 tsp" },
        { name: "Salt & black pepper", amt: "to taste" },
      ]},
      { section: "Tzatziki", items: [
        { name: "Greek yogurt (0%)", amt: "4 tbsp" },
        { name: "Cucumber (grated, squeezed dry)", amt: "¼ whole" },
        { name: "Garlic clove (minced)", amt: "1 clove" },
        { name: "Lemon juice", amt: "1 tsp" },
        { name: "Fresh dill or mint", amt: "small handful" },
      ]},
      { section: "Topping", items: [
        { name: "Cherry tomatoes (halved)", amt: "8–10 pieces" },
        { name: "Kalamata olives (sliced)", amt: "6 pieces" },
        { name: "Fresh parsley", amt: "small handful" },
      ]},
    ],
    steps: [
      "Marinate the chicken: Mix lemon juice, lemon zest, olive oil, garlic powder and oregano. Coat chicken breast and marinate 15 minutes minimum — 1 hour if you have it.",
      "Cook the rice: Rinse rice, cook in broth or water per packet instructions.",
      "Make the tzatziki: Grate cucumber, squeeze all water out through a cloth or hands. Mix with Greek yogurt, minced garlic, lemon juice and dill. Season and refrigerate.",
      "Sear the chicken: Pat dry. Heat a pan over high heat. Sear 4–5 minutes each side until golden and cooked through (internal 75°C). Rest 3 minutes, then slice.",
      "Build the bowl: Rice base, sliced chicken on top. Add cherry tomatoes and olives alongside. Spoon tzatziki over the chicken. Finish with fresh parsley.",
    ],
    hacks: [
      { title: "Lemon Zest in the Rub", text: "Zest packs more citrus than juice and holds up to heat — the oils in the skin give you that bright Greek flavour without going sour during cooking." },
      { title: "Squeeze the Cucumber Completely Dry", text: "Wet cucumber = watery tzatziki within minutes. Squeeze every drop out — then it stays thick and creamy for days." },
    ],
    notes: "Meal prep: marinate chicken overnight. Tzatziki keeps 3 days refrigerated. Swap chicken breast for thigh for extra richness.",
  },

  "miso-glazed-chicken-rice-bowl": {
    image: null,
    video: "",
    ingredients: [
      { section: "Rice", items: [
        { name: "Jasmine rice (dry)", amt: "{{carbG}}g" },
        { name: "Water", amt: "as needed" },
      ]},
      { section: "Chicken", items: [
        { name: "Chicken breast (boneless, skinless)", amt: "{{proteinG}}g raw" },
        { name: "Cooking spray", amt: "1 tsp" },
      ]},
      { section: "Miso Glaze", items: [
        { name: "White miso paste", amt: "2 tbsp" },
        { name: "Mirin", amt: "1 tbsp" },
        { name: "Soy sauce (low-sodium)", amt: "1 tbsp" },
        { name: "Rice vinegar", amt: "1 tsp" },
        { name: "Ginger (grated)", amt: "1 tsp" },
        { name: "Honey", amt: "1 tsp" },
      ]},
      { section: "Quick Pickle", items: [
        { name: "Radishes (thinly sliced)", amt: "5–6 pieces" },
        { name: "Rice vinegar", amt: "1 tbsp" },
        { name: "Salt", amt: "pinch" },
        { name: "Sugar", amt: "pinch" },
      ]},
      { section: "Topping", items: [
        { name: "Spring onions (sliced)", amt: "2 stalks" },
        { name: "Sesame seeds", amt: "1 tsp" },
      ]},
    ],
    steps: [
      "Quick-pickle the radishes: Toss sliced radishes with rice vinegar, a pinch each of salt and sugar. Set aside — they're ready in 10 minutes.",
      "Make the glaze: Whisk white miso, mirin, soy sauce, rice vinegar, grated ginger and honey until smooth.",
      "Cook the rice: Rinse and cook per packet instructions.",
      "Sear the chicken: Pat breast dry, season lightly. Heat pan over high, spray with oil. Sear 4 minutes each side until golden. Reduce heat to medium.",
      "Glaze and finish: Pour miso glaze over chicken, toss to coat. Let caramelise 60 seconds each side — watch it closely, miso burns fast. Internal temp 75°C.",
      "Rest and slice: Rest 2 minutes off heat, then slice against the grain.",
      "Build the bowl: Rice base, sliced chicken, pickled radish alongside. Finish with spring onion and sesame seeds.",
    ],
    hacks: [
      { title: "Cornstarch for the Glaze", text: "Add ½ tsp cornstarch to the miso glaze for a thicker, glossier finish that clings to the chicken instead of running off into the pan." },
      { title: "Watch the Miso", text: "Miso caramelises much faster than soy-based glazes — medium heat max once the glaze goes in. Thirty seconds too long and it goes from lacquered to burnt." },
    ],
    notes: "White miso available at Asian supermarkets. Mirin can be substituted with dry sherry + pinch of sugar.",
  },

