    steps: [
      "Make sushi rice: Cook rice per instructions. While hot, mix rice vinegar, sugar and salt until dissolved. Fold through warm rice gently. Fan to cool slightly.",
      "Season the tuna: Mix drained tuna with soy sauce, sesame oil, rice vinegar, grated ginger and chili flakes. Let sit 5 minutes.",
      "Cook edamame: Boil 3–4 minutes in salted water, then drain.",
      "Build the bowl: Sushi rice as the base. Arrange tuna in the centre. Place edamame, cucumber, carrot and avocado in separate sections around it. Top with spring onion and sesame seeds. Finish with sriracha.",
    ],
    hacks: [
      { title: "Dress While Warm", text: "Season the tuna while the rice is still warm — the residual warmth helps the sesame oil and soy absorb more deeply than dressing cold tuna." },
      { title: "The Arrangement is the Money Shot", text: "Poke bowls are a content goldmine — the colourful components arranged separately before mixing are one of the most photogenic food formats. Arrange each topping in its own section, tuna centred." },
    ],
    notes: "Canned tuna in water (not oil) keeps the calories lean. For fresh sushi-grade ahi tuna, dice into 2cm cubes and marinate the same way — the result is significantly better if available.",
